bool ctValidSyncSender(const char* value) {
  if (!value || strlen(value) != 12) return false;
  bool nonzero = false;
  for (size_t i = 0; i < 12; i++) {
    const char c = value[i];
    if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f'))) return false;
    nonzero |= c != '0';
  }
  const char low = value[1];
  const unsigned octetLow = low <= '9' ? low - '0' : low - 'a' + 10;
  return nonzero && !(octetLow & 1); // individual (unicast) MAC only
}

