String ctSyncMAC(bool ap) {
  uint8_t mac[6] = {};
  if (ap) {
    WiFi.softAPmacAddress(mac);
    // Config loads before WiFi.mode(): Arduino's AP getter then leaves bytes
    // untouched. Derive the actual factory AP address without starting WiFi.
    if (!CastleTekSyncPolicy::validMAC(mac)) esp_read_mac(mac, ESP_MAC_WIFI_SOFTAP);
  } else {
    WiFi.macAddress(mac);
  }
  char text[13];
  snprintf(text, sizeof(text), "%02x%02x%02x%02x%02x%02x", mac[0], mac[1], mac[2], mac[3], mac[4], mac[5]);
  return text;
}

