void ctSyncResponse(AsyncWebServerRequest* request, int status, bool accepted = false) {
  AsyncJsonResponse* response = new AsyncJsonResponse(3072);
  JsonObject object = response->getRoot();
  ctWriteSyncStatus(object);
  if (accepted) object["accepted"] = true;
  response->addHeader("Cache-Control", "no-store");
  response->setCode(status);
  response->setLength();
  request->send(response);
}

