void castleTekWLEDRegisterSyncRoutes() {
  server.on(castleTekWLEDRoute("/sync"), HTTP_GET, [](AsyncWebServerRequest* request) {
    if (!correctPIN && strlen(settingsPIN)) { request->send(401); return; }
    if (!requestJSONBufferLock(JSON_LOCK_SERVER)) { request->send(409); return; }
    ctSyncResponse(request, 200);
    releaseJSONBufferLock();
  });
  auto* handler = new AsyncCallbackJsonWebHandler(castleTekWLEDRoute("/sync"), [](AsyncWebServerRequest* request) {
    if (request->url() != castleTekWLEDRoute("/sync")) { request->send(404); return; }
    if (!correctPIN && strlen(settingsPIN)) { request->send(401); return; }
    if (castleTekWLEDBackupFailed()) { request->send(503); return; }
    if (!requestJSONBufferLock(JSON_LOCK_SERVER)) { request->send(409); return; }
    if (!CastleTekSyncPolicy::validJSONText(static_cast<uint8_t*>(request->_tempObject), request->contentLength())) {
      releaseJSONBufferLock(); request->send(400); return;
    }
    const DeserializationError error = deserializeJson(*pDoc, static_cast<uint8_t*>(request->_tempObject), request->contentLength());
    JsonObject root = pDoc->as<JsonObject>();
    SyncSettings expected, desired;
    if (error || root.isNull() || root.size() != 3 || !root["schema"].is<unsigned>() || root["schema"].as<unsigned>() != 4 ||
        !ctParseSyncSettings(root["expected"], expected, false) || !ctParseSyncSettings(root["settings"], desired, true)) {
      releaseJSONBufferLock(); request->send(400); return;
    }
    if (!(ctCurrentSync() == expected) || configNeedsWrite) {
      releaseJSONBufferLock(); request->send(409); return;
    }
    ctApplySync(desired);
    ctSyncSaveError = false;
    configNeedsWrite = true;
    lastEditTime = millis();
    ctSyncResponse(request, 202, true);
    releaseJSONBufferLock();
  });
  handler->setMethod(HTTP_POST);
  handler->setMaxContentLength(4096);
  server.addHandler(handler);
}

void castleTekWLEDSerializeSyncInfo(JsonObject root) {
  JsonObject sync = root.createNestedObject("sync");
  sync["schema"] = 4;
  sync["available"] = true;
  sync["espNowAvailable"] = CT_SYNC_ESPNOW_AVAILABLE;
  JsonArray disabled = sync.createNestedArray("disabledFeatures");
  disabled.add("mqtt"); disabled.add("hue"); disabled.add("dmx");
}

